self.addEventListener('fetch',event=>{const request=event.request,url=new URL(request.url);if(request.method!=='GET'||url.origin!==location.origin||url.pathname.startsWith('/api/')||url.pathname==='/ranking-catalog.json')return;if(request.mode==='navigate'){event.respondWith(fetch(request).then(response=>{if(response.ok){const copy=response.clone();event.waitUntil(caches.open(CACHE).then(c=>c.put(request,copy)))}return response}).catch(()=>caches.match(request).then(r=>r||caches.match(url.pathname.startsWith('/wall/')?'/wall/':url.pathname.startsWith('/lab')?'/lab/':url.pathname.startsWith('/stages')?'/stages/':'/'))));return}event.respondWith(caches.open(CACHE).then(async cache=>{const saved=await cache.match(request);if(saved)return saved;const response=await fetch(request);if(response.ok)await cache.put(request,response.clone());return response}))});
